tool_input.function:
() => {
  // Check the single script content
  const script = document.querySelector('script');
  const scriptContent = script ? script.textContent : 'no script';

  // Check if there's a LiveView hook that handles graph-ctrl-btn
  // Look for any event delegation on document/window for data-action

  // Check what the SVG container element is
  const container = document.querySelector('[id*="graph"], [class*="graph-container"], [phx-hook*="graph"], [data-phx-hook]');
  const containerInfo = container ? {
    id: container.id,
    classes: container.className,
    phxHook: container.getAttribute('phx-hook'),
    dataPhxHook: container.getAttribute('data-phx-hook'),
    tagName: container.tagName
  } : null;

  // Look for all elements with phx-hook
  const hooksEls = Array.from(document.querySelectorAll('[phx-hook]')).map(el => ({
    id: el.id,
    hook: el.getAttribute('phx-hook'),
    tagName: el.tagName,
    classes: el.className.substring(0, 50)
  }));

  return {
    scriptPreview: scriptContent.substring(0, 1000),
    containerInfo,
    hooksEls,
  };
}
